def find_permutations(k, arr):
    n = 2 ** k
    # Check if the sum of all elements in arr is even
    if sum(arr) % 2 != 0:
        return 'Fou'

    # Initialize p and q as permutations of 0 to 2^k - 1
    p = list(range(n))
    q = list(range(n))

    # Try to find a solution
    for i in range(n):
        for j in range(n):
            if (p[i] ^ q[j]) == arr[i]:
                p[i], q[j] = q[j], p[i]
                break

    # Check if the found permutations satisfy the condition
    for i in range(n):
        if (p[i] ^ q[i]) != arr[i]:
            return 'Fou'

    return 'Shi', p, q

# Read input
k = int(input().strip())
arr = list(map(int, input().strip().split()))

# Find and print the result
result = find_permutations(k, arr)
if result == 'Fou':
